import React, { useState, useEffect } from 'react';
import { useBot } from '../contexts/BotContext';

const FileManager = () => {
  const { botState } = useBot();
  const [files, setFiles] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);

  useEffect(() => {
    // Simulate loading files
    const mockFiles = [
      { id: 1, name: 'config.json', size: '2.1 KB', type: 'JSON', lastModified: '2024-01-15' },
      { id: 2, name: 'bot_log.txt', size: '15.7 KB', type: 'TXT', lastModified: '2024-01-15' },
      { id: 3, name: 'data_processor.py', size: '8.3 KB', type: 'Python', lastModified: '2024-01-14' },
      { id: 4, name: 'main_bot.py', size: '12.1 KB', type: 'Python', lastModified: '2024-01-14' },
    ];
    setFiles(mockFiles);
  }, []);

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      // Simulate upload progress
      setUploadProgress(0);
      const interval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            return 100;
          }
          return prev + 10;
        });
      }, 100);
    }
  };

  const handleFileDelete = (fileId) => {
    setFiles(files.filter(file => file.id !== fileId));
  };

  const handleFileSelect = (file) => {
    setSelectedFile(file);
  };

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900 mb-2">File Manager</h1>
        <p className="text-gray-600">Manage bot configuration files and logs</p>
      </div>

      {/* Upload Section */}
      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Upload Files</h2>
        <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
          <input
            type="file"
            onChange={handleFileUpload}
            className="hidden"
            id="file-upload"
          />
          <label
            htmlFor="file-upload"
            className="cursor-pointer text-blue-600 hover:text-blue-800 font-medium"
          >
            Click to upload files
          </label>
          <p className="text-sm text-gray-500 mt-2">or drag and drop</p>
        </div>
        {uploadProgress > 0 && uploadProgress < 100 && (
          <div className="mt-4">
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              ></div>
            </div>
            <p className="text-sm text-gray-600 mt-2">Uploading... {uploadProgress}%</p>
          </div>
        )}
      </div>

      {/* Files List */}
      <div className="bg-white rounded-lg shadow">
        <div className="px-6 py-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">Files</h2>
        </div>
        <div className="divide-y divide-gray-200">
          {files.map((file) => (
            <div
              key={file.id}
              className={`px-6 py-4 hover:bg-gray-50 cursor-pointer ${
                selectedFile?.id === file.id ? 'bg-blue-50' : ''
              }`}
              onClick={() => handleFileSelect(file)}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="flex-shrink-0">
                    <div className="w-8 h-8 bg-gray-100 rounded flex items-center justify-center">
                      <span className="text-xs text-gray-600 font-medium">
                        {file.type === 'Python' ? '🐍' : file.type === 'JSON' ? '📄' : '📝'}
                      </span>
                    </div>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">{file.name}</p>
                    <p className="text-sm text-gray-500">
                      {file.size} • {file.type} • {file.lastModified}
                    </p>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      // Handle file preview/download
                    }}
                    className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                  >
                    View
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleFileDelete(file.id);
                    }}
                    className="text-red-600 hover:text-red-800 text-sm font-medium"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* File Details */}
      {selectedFile && (
        <div className="mt-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">File Details</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-sm font-medium text-gray-500">Name</p>
              <p className="text-sm text-gray-900">{selectedFile.name}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">Size</p>
              <p className="text-sm text-gray-900">{selectedFile.size}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">Type</p>
              <p className="text-sm text-gray-900">{selectedFile.type}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">Last Modified</p>
              <p className="text-sm text-gray-900">{selectedFile.lastModified}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FileManager;
